function createDiscount(percent, capKobo) {
  const rate = percent / 100;
  return (priceKobo) => Math.min(Math.round(priceKobo * rate), capKobo);
}

const tenOff = createDiscount(10, 500000);
const staff = createDiscount(25, 1000000);
console.log(tenOff(850000), tenOff(9000000), staff(850000));

