function after(n, fn) {
  let calls = 0;
  return (...args) => {
    calls += 1;
    if (calls < n) return undefined;
    return fn(...args);
  };
}

const reward = after(3, (orderId) => `reward for ${orderId}`);
console.log(reward("ORD-1"), reward("ORD-2"), reward("ORD-3"), reward("ORD-4"));

