function createAccount() {
  let balanceKobo = 0;
  return {
    deposit(kobo) {
      balanceKobo += kobo;
    },
    withdraw(kobo) {
      if (kobo > balanceKobo) return "insufficient funds";
      balanceKobo -= kobo;
    },
    balance: () => balanceKobo,
  };
}

const account = createAccount();
account.deposit(5000);
console.log(account.withdraw(8000));
account.withdraw(2000);
console.log(account.balance(), account.balanceKobo);
